effect.shader:
#define PI 3.14159265359
void main() {
vec2 uv = acScreenNorm;
vec4 texColor = texture2DCv(inputImg.texture, uv);
float baseAlpha = texColor.a;
vec2 st = (uv - 0.5) - vec2(position.x, -position.y) * 0.5;
st.x *= acScreenSize.x / max(acScreenSize.y, 1.0);
st /= max(scale, 0.001);
float rad = length(st);
float angle = atan(st.y, st.x);
float r = max(rad, 0.001);
float u = depth / r + acTime * speed;
float v = angle / PI + r * twist;
float ringDist = abs(fract(u * rings) - 0.5);
float line = smoothstep(thickness, thickness * 0.5, ringDist);
float wave = sin(v * PI * 4.0 + acTime) * 0.1;
float distortedRingDist = abs(fract(u * rings + wave) - 0.5);
float glow = exp(-distortedRingDist * 10.0) * glowIntensity;
float colorMix = sin(u * 2.0) * 0.5 + 0.5;
vec3 ringColor = mix(color1.rgb, color2.rgb, colorMix);
vec3 finalColor = ringColor * (line + glow);
float centerFade = smoothstep(0.0, 0.2, r);
finalColor *= centerFade;
vec4 result;
vec3 tcSafe = texColor.rgb / max(texColor.a, 0.001);
if (blendMode == 0) {
result = vec4(finalColor, 1.0);
} else if (blendMode == 2) {
result = vec4(1.0 - (1.0 - tcSafe) * (1.0 - finalColor), 1.0);
} else {
result = vec4(tcSafe + finalColor, 1.0);
}
result = clamp(result, 0.0, 1.0);
result *= baseAlpha;
vec4 outputColor = mix(texColor, result, alpha);
gl_FragColor = outputColor;
}
